249	fn merge_defense(section: &mut DefenseSection, dir: &Path, source: RecordSource) -> Result<()> {
250	    for s in defense::meta_stressors::load(dir)? {
251	        let id = s.id.clone();
252	        upsert(
253	            &mut section.meta_stressors,
254	            |x| x.id == id,
255	            SnapshotMetaForce {
256	                id: s.id,
257	                shortname: s.shortname,
258	                description: s.description,
259	                naive_change: String::new(),
260	                outcomes: String::new(),
261	                attractor_id: String::new(),
262	                kind: ForceKind::Stressor,
263	                source,
264	            },
265	        );
266	    }
267	
268	    for a in defense::meta_attractors::load(dir)? {
269	        let id = a.id.clone();
270	        upsert(
271	            &mut section.meta_attractors,
272	            |x| x.id == id,
273	            SnapshotAttractor {
274	                id: a.id,
275	                name: a.name,
276	                description: a.description,
277	                positive_state: a.positive_state,
278	                negative_state: a.negative_state,
279	                source,
280	            },
281	        );
282	    }
283	
284	    for p in defense::meta_purposes::load(dir)? {
285	        let id = p.id.clone();
286	        upsert(
287	            &mut section.meta_purposes,
288	            |x| x.id == id,
289	            SnapshotMetaForce {
290	                id: p.id,
291	                shortname: p.shortname,
292	                description: p.description,
293	                naive_change: p.naive_change,
294	                outcomes: p.outcomes,
295	                attractor_id: p.attractor_id,
296	                kind: ForceKind::Purpose,
297	                source,
298	            },
299	        );
300	    }
301	
302	    upsert_string_list(&mut section.personas, &defense::artifacts::list_personas(dir)?);
303	    upsert_string_list(
304	        &mut section.strategies,
305	        &defense::artifacts::list_strategies(dir)?,
306	    );
307	    upsert_string_list(&mut section.progress, &defense::artifacts::list_progress(dir)?);
308	    upsert_string_list(&mut section.pitches, &defense::artifacts::list_pitches(dir)?);
309	
310	    Ok(())
311	}
312	
313	fn upsert<T, F>(items: &mut Vec<T>, mut matches: F, item: T)
314	where
315	    F: FnMut(&T) -> bool,
316	{
317	    if let Some(existing) = items.iter_mut().find(|x| matches(x)) {
318	        *existing = item;
319	    } else {
320	        items.push(item);
321	    }
322	}
323	
324	fn upsert_string_list(dest: &mut Vec<String>, incoming: &[String]) {
325	    for name in incoming {
326	        if !dest.iter().any(|x| x == name) {
327	            dest.push(name.clone());
328	        }
329	    }
330	}
