332	/// Convenience wrapper for a single ledger directory.
333	pub fn load_landscape_snapshot_from_dir(
334	    dir: &Path,
335	    include_defense: bool,
336	) -> Result<LandscapeSnapshot> {
337	    load_landscape_snapshot_from_sources(
338	        &LandscapeSources {
339	            sidecar_dir: Some(dir.to_path_buf()),
340	            working_dir: None,
341	        },
342	        include_defense,
343	    )
344	}
